#!/usr/bin/env -S uv run --script
# Synced from bootstrap: macos/tools/cli/tasks/keychain-delete.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Delete a generic password from the login keychain (exact service + account match)"
# MISE raw=true
# MISE tools={uv="latest", python="3.14"}
# USAGE flag "--service <service>" required=#true help="Keychain item service (exact match)"
# USAGE flag "--account <account>" required=#true help="Keychain item account (exact match)"

import os
import re
import shutil
import subprocess
import sys

# The [[:space:]] class of the shell
SPACE = "[ \t\n\r\f\v]"


def die(msg):
  print(f"error: {msg}", file=sys.stderr, flush=True)
  sys.exit(1)


def strip_newlines(text):
  """Remove the trailing newlines, as a command substitution does."""
  return text.rstrip("\n")


def login_keychain():
  """Resolve the login keychain path (output is a quoted, indented path)."""
  proc = subprocess.run(["security", "login-keychain"], check=False, stdout=subprocess.PIPE)
  if proc.returncode:
    sys.exit(128 - proc.returncode if proc.returncode < 0 else proc.returncode)
  pattern = re.compile(rf'^{SPACE}*"(.*)"{SPACE}*$')
  lines = proc.stdout.decode("utf-8", "surrogateescape").split("\n")
  return strip_newlines("\n".join(pattern.sub(r"\1", line) for line in lines))


def attr(info, name):
  """Extract one attribute from `security` output, e.g.
  "acct"<blob>="foo"
  0x00000007 <blob>="label"
  "cdat"<timedate>=0x3230...  "20240115093012Z\\000"
  """
  pattern = re.compile(rf'^{SPACE}*"?{re.escape(name)}"?{SPACE}*<')
  line = next((line for line in info.split("\n") if pattern.search(line)), None)
  if line is None:
    return ""
  val = line.partition("=")[2] if "=" in line else line
  if val == "<NULL>":
    return ""
  if val.startswith("0x"):
    # hex dump followed by printable form
    val = val.partition(" ")[2] if " " in val else val
  val = re.sub(rf"^{SPACE}+", "", val)  # trim leading whitespace
  val = val.removeprefix('"')
  val = val.removesuffix('"')
  val = val.removesuffix("\\000")
  return val


def fmt_date(d):
  if re.fullmatch(r"[0-9]{14}Z", d):
    return f"{d[0:4]}-{d[4:6]}-{d[6:8]} {d[8:10]}:{d[10:12]}:{d[12:14]} UTC"
  return d


def row(label, value):
  if value:
    print(f"  {label:<9} {value}", flush=True)


def main():
  service = os.environ.get("usage_service", "")
  account = os.environ.get("usage_account", "")

  if not service:
    die("--service must not be empty")
  if not account:
    die("--account must not be empty")
  if os.uname().sysname != "Darwin":
    die("macOS only")
  if not shutil.which("security"):
    die("'security' CLI not found")
  if not os.isatty(0):
    die("interactive terminal required (stdin is not a TTY)")

  keychain = login_keychain()
  if not os.path.isfile(keychain):
    die(f"login keychain not found: {keychain}")

  # Look up the item's attributes only. Without -g/-w the secret is never read,
  # so this does not trigger a keychain access prompt.
  proc = subprocess.run(
    ["security", "find-generic-password", "-s", service, "-a", account, keychain],
    check=False,
    stdout=subprocess.PIPE,
    stderr=subprocess.STDOUT,
  )
  info = strip_newlines(proc.stdout.decode("utf-8", "surrogateescape"))
  rc = proc.returncode

  if rc == 44:
    print(
      f'No generic password in login keychain for service="{service}" account="{account}"',
      file=sys.stderr,
      flush=True,
    )
    sys.exit(1)
  elif rc != 0:
    die(f"security find-generic-password failed (exit {rc}): {info}")

  print("Found keychain item:", flush=True)
  row("Keychain", keychain)
  row("Class", "generic password")
  row("Label", attr(info, "0x00000007"))
  row("Service", attr(info, "svce"))
  row("Account", attr(info, "acct"))
  row("Kind", attr(info, "desc"))
  row("Comment", attr(info, "icmt"))
  row("Creator", attr(info, "crtr"))
  row("Created", fmt_date(attr(info, "cdat")))
  row("Modified", fmt_date(attr(info, "mdat")))
  print(flush=True)

  # read -p writes its prompt on stderr. At the end of the input, read fails,
  # and set -e stops the task with code 1.
  sys.stderr.write("Delete this item? [y/N] ")
  sys.stderr.flush()
  line = sys.stdin.readline()
  if not line:
    sys.exit(1)
  reply = line.rstrip("\n").strip(" \t\n")
  if reply not in ("y", "Y") and reply.lower() != "yes":
    print("Aborted. Nothing deleted.", flush=True)
    sys.exit(0)

  proc = subprocess.run(
    ["security", "delete-generic-password", "-s", service, "-a", account, keychain],
    check=False,
    stdout=subprocess.DEVNULL,
  )
  if proc.returncode:
    sys.exit(128 - proc.returncode if proc.returncode < 0 else proc.returncode)
  print("Deleted.", flush=True)


if __name__ == "__main__":
  main()
